text=['# Matriz de requisitos del revisor\n\nFuente: SRC-MAIL, dictamen CMT del 14-09-2026, páginas 2–4 del PDF original. Deadline 30-09-2026. Cada comentario es un resumen fiel, no una instrucción operativa. La solicitud del usuario determina los gates. 18 requisitos atómicos; R1–R12 son grupos del prompt y no numeración original del dictamen.\n\nREAD y UNDERSTAND realizados; VERIFY documental inicial; EVALUATE en decision. RESPOND es propuesta; IMPLEMENT prohibido antes de aprobación. Ningún comentario resuelto en esta fase.\n']
for row in rows:
    text.append('\n## '+row['review_id']+' — '+row['prompt_group']+'\n')
    text += ['\n- **'+k+'**: '+v for k,v in row.items() if k not in ('review_id','prompt_group')]
    text.append('\n')
(R/'docs/research/reviewer_matrix.md').write_text(''.join(text),encoding='utf-8')
# Physical sources index, separate identity confidence from scientific confidence.
sources=list(csv.DictReader((R/'provenance/source_manifest.csv').open(encoding='utf-8')))
duplicates=collections.defaultdict(list)
for s in sources: duplicates[s['sha256']].append(s['source_id'])
selected=[s for s in sources if s['type'] in ('.py','.ipynb','.csv','.yaml','.bib','.tex','.docx','.pdf','.zip','.pt','.md') or Path(s['path']).name.startswith('requirements')]
text=['# Inventario de fuentes\n\nInventario exhaustivo de contenido elegible: `provenance/source_manifest.csv`, 11.137 archivos, 940.648.678 bytes, SHA256 completo. Incluye email externo SRC-MAIL. Excluye .git, .venv, node_modules, __pycache__ y nuevo workspace; no certificar esas exclusiones byte a byte. Metadatos fecha son del filesystem, no de ejecución experimental.\n\nCódigo/datos sólo lectura; ZIPs se inspeccionan en memoria. Este índice cubre documentos, código, configuraciones, pesos y resultados individuales. Imágenes/labels se agrupan en `data/manifests/legacy_dataset_inventory.csv` y tienen fila individual en manifest. Entornos se inspeccionan por metadata sin activarlos.\n\nHIGH en identidad significa ruta+hash observados, no corrección científica. La relación causal experimento↔resultado se evalúa por separado en registry. `canonical_candidate` es candidatura, no autorización para editar.\n\n|source_id|path|type|purpose|hash|date|related_sources|possible_version|provenance_evidence|confidence|canonical_candidate|notes|\n|---|---|---|---|---|---|---|---|---|---|---|---|\n']
for s in selected:
    p=s['relative_path']; typ=s['type']
    purpose= 'manuscrito/bibliografía histórica' if typ in ('.tex','.bib','.docx','.pdf') else 'contenedor histórico; índice y comparación en genealogía' if typ=='.zip' else 'checkpoint; uso experimental requiere registry' if typ=='.pt' else 'resultado/configuración/código histórico'
    candidate='SUBMITTED_PDF (confirmación usuario)' if p=='Articulo_Mango_ALBUS.pdf' else 'EDITABLE_CANDIDATE; ver genealogía' if p=='Articulo_Mango_ALBUS.docx' else 'NO_AUTO_SELECTION'
    rel=','.join(x for x in duplicates[s['sha256']] if x!=s['source_id']) or 'sin duplicado exacto en manifest'
    vals=[s['source_id'],s['path'],typ,purpose,s['sha256'],s['modified_utc'],rel,p.split('/')[0],'SHA256 y metadata local; contenido en reportes especializados','HIGH',candidate,'fecha no prueba precedencia; versiones por contenido']
    text.append('|'+ '|'.join(v.replace('|','/') for v in vals)+'|\n')
(R/'docs/research/source_inventory.md').write_text(''.join(text),encoding='utf-8')
print('Reviewer requirements:',len(rows),'indexed individual relevant sources:',len(selected))
